cd /root/autodl-tmp/event-gated-adaptive-horizon && python3 -c "
import json

# === exp_057: extract civo/ve_ratio and eval_return ===
print('=== exp_057 civo/ve_ratio + eval_return ===')
with open('logdir/exp_057_frozen_dt_emb_walker_s2/metrics.jsonl') as f:
    for line in f:
        m = json.loads(line)
        step = m.get('step', 0)
        if 'civo/ve_ratio' in m:
            print(f'  step={step}, civo/ve_ratio={m[\"civo/ve_ratio\"]:.6f}')
        elif 'eval_return' in m and step >= 5000:
            print(f'  step={step}, eval_return={m[\"eval_return\"]:.2f}')

print()

# === exp_009a baseline s2: compute ve_ratio = value_mean / eval_return ===
print('=== exp_009a baseline s2: value_mean + eval_return ===')
eval_returns = {}
value_means = {}
with open('logdir/exp_009a_baseline_walker_s2/metrics.jsonl') as f:
    for line in f:
        m = json.loads(line)
        step = m.get('step', 0)
        if 'eval_return' in m:
            eval_returns[step] = m['eval_return']
        if 'value_mean' in m:
            value_means[step] = m['value_mean']

# Compute ve_ratio at eval steps
for step in sorted(eval_returns.keys()):
    if step >= 5000:
        ev = eval_returns[step]
        # Find closest value_mean
        vm = value_means.get(step, None)
        if vm is None:
            # Try nearby steps
            for delta in [0, 5000, -5000, 10000, -10000]:
                if step + delta in value_means:
                    vm = value_means[step + delta]
                    break
        if vm is not None and ev > 0:
            ve = vm / ev
            print(f'  step={step}, eval_return={ev:.2f}, value_mean={vm:.2f}, ve_ratio={ve:.4f}')
        else:
            print(f'  step={step}, eval_return={ev:.2f}, value_mean=N/A')
"

